def need(ok,msg):
 if not ok: raise ValueError(msg)

def get(url,headers={}):
 with urlopen(Request(url,headers=headers),timeout=90) as r:return r.read()

def source(c,name=None):
 found=[s for s in SOURCES if s['collectionId']==c and (name is None or s['name']==name)]
 need(len(found)==1,f'Ambiguous source {c}/{name}');return found[0]

def path(c,name=None):return INPUT/c/source(c,name)['name']

def number(v):
 if v is None or str(v).strip() in ['', '..','...','x','F','-','—','..x']:return None
 try:
  n=float(str(v).strip().replace(',',''));return n if math.isfinite(n) else None
 except ValueError:return None

def csv_rows(c,name=None,member=None,prefilter=None):
 p=path(c,name);f=p.open('rb');archive=None
 if p.suffix=='.zip':
  f.close();archive=zipfile.ZipFile(p);m=member or next(n for n in archive.namelist() if n.endswith('.csv') and 'Meta' not in n);f=archive.open(m)
 h=next(csv.reader([f.readline().decode('utf-8-sig')]));count=0;selected=0
 for line in f:
  count+=1
  if prefilter and not prefilter(line):continue
  a=next(csv.reader([line.decode('utf-8-sig')]));selected+=1;yield dict(zip(h,a)),count+1
 f.close()
 if archive:archive.close()
 INSPECTIONS[c+'/'+(member or p.name)]={'originalDataRows':count,'parsedRows':selected,'columns':h}

def workbook(c,name=None,member=None):
 p=path(c,name);data=p.read_bytes()
 if member:data=zipfile.ZipFile(io.BytesIO(data)).read(member)
 ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
 with zipfile.ZipFile(io.BytesIO(data)) as z:
  shared=[''.join(n.text or '' for n in t.findall('.//s:t',ns)) for t in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',ns)] if 'xl/sharedStrings.xml' in z.namelist() else []
  rels={r.attrib['Id']:r.attrib['Target'] for r in ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))};out={}
  for sh in ET.fromstring(z.read('xl/workbook.xml')).findall('s:sheets/s:sheet',ns):
   t=rels[sh.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']];part=t.lstrip('/') if t.startswith('/') else 'xl/'+t;rows={}
   for r in ET.fromstring(z.read(part)).findall('s:sheetData/s:row',ns):
    row={}
    for a in r.findall('s:c',ns):
     col=re.match('[A-Z]+',a.attrib['r']).group();i=0
     for x in col:i=i*26+ord(x)-64
     v=a.find('s:v',ns);v=v.text if v is not None else None;ty=a.attrib.get('t')
     if ty=='s':v=shared[int(v)] if v is not None else None
     elif ty=='inlineStr':v=''.join(q.text or '' for q in a.findall('.//s:t',ns))
     elif ty not in ['str','e','b'] and v is not None:v=number(v)
     row[i-1]=v
    rows[int(r.attrib['r'])]=row
   out[sh.attrib['name']]=rows
  INSPECTIONS[c+'/'+(member or p.name)]={'worksheetRows':{k:len(v) for k,v in out.items()},'originalWorkbook':'Cached source cell values; formulas not recalculated.'};return out

def col(k,label=None,unit=None):return {'key':k,'label':label or k.replace('_',' ').capitalize(),'type':'number' if unit else 'text',**({'unit':unit} if unit else {})}

