def csv_partitions(c,s,tabs,indices,member):
 inspection=INSPECTIONS.get(c+'/'+str(member)) or INSPECTIONS.get(c+'/'+s['name']);need(inspection is not None,'Missing full CSV rowcount for partition lineage')
 tabs=sorted(tabs,key=lambda t:int(re.search(r'_p(\d+)\.parquet$',t['parquetName']).group(1)))
 need(sum(int(t['row_count']) for t in tabs)==inspection['originalDataRows'],'CSV partition counts do not reconcile with original row ordinals')
 selected=[];start=2
 for t in tabs:
  end=start+int(t['row_count'])
  if any(start<=i<end for i in indices):selected.append(t)
  start=end
 need(selected and all(2<=i<start for i in indices),'Selected row falls outside catalogue partitions')
 return selected

