 indices=CELL_SOURCE_ROWS.get(id,[]) or [int(v) for r in rows for k,val in r.items() if k=='source_row' or k.endswith('_source_row') or k=='source_rows' for v in str(val).split(';') if str(v).isdigit()]
 if indices and all(not t['worksheet'] and not t['sqlite_table'] for t in tabs):
  tabs=csv_partitions(c,s,tabs,indices,member)
 d={'id':id,'title':title,'description':notes[0],'topic':'Regional context','geography':geography,'status':status,'timeLabel':('2021 Census; income reference 2020' if id.startswith('census-') else ' — '.join(dict.fromkeys([min(str(r[time]) for r in rows),max(str(r[time]) for r in rows)]))),'sourceName':'NHHR '+c+' — '+('BC Stats' if c in ['DATA-C003','DATA-C038'] else 'CMHC' if c=='DATA-C004' else 'CREA' if c=='DATA-C005' else 'Statistics Canada'),'sourceUrl':publisher_url(c,member),'datasetId':s['datasetId'],'tableName':tabs[0]['table_name'],'notes':notes,'columns':[{**c,'label':readable(c['label'])} for c in columns],'rows':rows,'defaultMetric':metric,'entityField':entity,'timeField':time}
 if geography!='none':d['boundaryKeyField']=geography+'_code'
 if filters:d['defaultFilters']=filters
 LINEAGE[id]={'collectionId':c,'sourceFile':s['name'],'sourceSha256':s['sha256'],'tableNames':[t['table_name'] for t in tabs],'archiveMember':member,'worksheet':sheet,'releasedRows':len(rows),'selection':notes,'selectedOriginalCsvRows':sorted(set(indices))}
 return d

